<script setup lang="ts">import {ref,onMounted} from 'vue';import {measurements} from '../stores/measurements';import {calibrations} from '../stores/calibrations';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import StatusPill from '../components/common/StatusPill.vue';
const name=ref(''),text=ref(''),description=ref(''),calName=ref(''),calSource=ref(''),reimportId=ref(''),reimportText=ref('');const {error,busy,act}=useTask();const reimportTask=useTask();const calTask=useTask();
onMounted(()=>Promise.all([measurements.load(),calibrations.load()]));
async function file(e:Event,target:'text'|'reimport'){const f=(e.target as HTMLInputElement).files?.[0];if(f){const s=await f.text();if(target==='text')text.value=s;else reimportText.value=s}}
function submit(){act(async()=>{await measurements.create({name:name.value,csv_text:text.value,description:description.value});name.value='';text.value=''})}
function reimport(){reimportTask.act(async()=>{await measurements.reimport(reimportId.value,reimportText.value);reimportText.value='';await calibrations.load()})}
function estimate(){calTask.act(async()=>{await calibrations.create({name:calName.value,measurement_set_id:calSource.value});calName.value=''})}
function publish(id:string){calTask.act(async()=>{await calibrations.publish(id)})}
function minPair(c:any){let m=Infinity;const p=c.pair_counts||[];for(let i=0;i<p.length;i++)for(let j=i+1;j<(p[i]||[]).length;j++)m=Math.min(m,p[i][j]);return m===Infinity?'—':m}
</script><template><PageHeading index="04 / 联合校准" title="原浆同涨同跌，扰动就该一起动。" note="按检测批号配对的多原浆实测估计Spearman秩相关，缺测留空不补零、按成对完整样本计算。校准发布后供情景选择；源数据更新使旧校准失效并拒绝新试算，已完成结果仍可回读。"/><div class="two-col"><section><Notice :message="measurements.error.value"/><article v-for="r in measurements.items.value" :key="r.id" class="scenario-row"><p class="eyebrow">PAIRED BATCH RECORDS · v{{r.version}}</p><h2>{{r.name}}</h2><dl><div><dt>检测批号</dt><dd>{{r.batches}}</dd></div><div><dt>配对记录</dt><dd>{{r.rows.length}}</dd></div></dl><p>{{r.description}}</p></article></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>导入配对实测记录</h2><label>记录集名称<input v-model="name" required minlength="2"></label><label>CSV文件<input type="file" accept=".csv" @change="e=>file(e,'text')"></label><label>配对实测CSV<textarea v-model="text" rows="7" required placeholder="batch_id,material_id,strength,whiteness,recycled,cost（缺测留空，不补零）"></textarea></label><label>检测说明<input v-model="description"></label><Notice :message="error"/><button :disabled="busy">校验并导入实测</button><h2 style="margin-top:32px">更新源数据（旧校准失效）</h2><label>目标记录集<select v-model="reimportId" required><option value="" disabled>选择记录集</option><option v-for="r in measurements.items.value" :key="r.id" :value="r.id">{{r.name}} · v{{r.version}}</option></select></label><label>新版CSV文件<input type="file" accept=".csv" @change="e=>file(e,'reimport')"></label><label>新版配对实测CSV<textarea v-model="reimportText" rows="5" required></textarea></label><Notice :message="reimportTask.error.value"/><button type="button" :disabled="reimportTask.busy.value||!reimportId" @click="reimport">导入新版并使旧校准失效</button></form><aside v-else class="margin-note">只读账号可核查配对实测与校准状态。导入与发布需要分析师权限。</aside></div><div class="two-col" style="margin-top:40px"><section><Notice :message="calibrations.error.value"/><article v-for="r in calibrations.items.value" :key="r.id" class="scenario-row"><p class="eyebrow">JOINT CALIBRATION · 源v{{r.source_version}}</p><h2>{{r.name}} <StatusPill :status="r.status"/></h2><dl><div><dt>扰动维度</dt><dd>{{r.keys.length}}</dd></div><div><dt>最小成对样本</dt><dd>{{minPair(r)}}</dd></div><div><dt>最小特征值</dt><dd class="seed-dd">{{r.min_eigenvalue===null?'—':Number(r.min_eigenvalue).toFixed(4)}}</dd></div></dl><p v-if="r.reason" class="method-note">{{r.reason}}</p><p v-if="r.assumption" class="method-note">{{r.assumption}}</p><button v-if="canWrite()&&r.status==='draft'" :disabled="calTask.busy.value" @click="publish(r.id)">发布校准（供情景选择）→</button></article></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="estimate"><h2>估计联合扰动校准</h2><label>校准名称<input v-model="calName" required minlength="2"></label><label>配对实测记录集<select v-model="calSource" required><option value="" disabled>选择记录集</option><option v-for="r in measurements.items.value" :key="r.id" :value="r.id">{{r.name}} · v{{r.version}}</option></select></label><p class="method-note">样本不足或相关结构不可实现时，校准保存为"估计失败"并写明原因，不会退化为独立抽样。</p><Notice :message="calTask.error.value"/><button :disabled="calTask.busy.value||!calSource">估计并保存草稿</button></form></div></template>
